import { useState, useEffect, useCallback, useRef } from "react";
import { useNavigate, useParams } from "react-router-dom";
import {
  createPkRoom,
  updatePkRoom,
  getPkRoomsChannel,
  fetchMyImportRecords,
  fetchWaitingRooms,
  joinPkRoom,
  deletePkRoom,
} from "@/utils/pkApi";
import { PkRoom, ImportRecord } from "@/types/pk";
import { useWordStore } from "@/store/useWordStore";
import { usePkRoom } from "@/hooks/usePkRoom";
import { getUserInfo } from "@/utils/userInfo";
import { showToast } from "@/utils/toast";
import { PkLobbyView } from "@/components/pk/PkLobbyView";
import { PkCreateView } from "@/components/pk/PkCreateView";
import { PkWaitingView } from "@/components/pk/PkWaitingView";

type View = "lobby" | "create" | "waiting";

export default function PkLobby() {
  const { roomId } = useParams();
  const navigate = useNavigate();
  const userInfo = getUserInfo();
  const words = useWordStore((s) => s.words);

  const [view, setView] = useState<View>("lobby");
  const [isHost, setIsHost] = useState(false);
  const [activeRoomId, setActiveRoomId] = useState<string>("");
  const closingRef = useRef(false);

  const [questionCount, setQuestionCount] = useState(10);
  const [timePerQuestion, setTimePerQuestion] = useState(15);
  const [spellingRatio, setSpellingRatio] = useState(0);
  const [matchMode, setMatchMode] = useState<"same" | "different">("same");
  const [sourceType, setSourceType] = useState<"import" | "random">("random");
  const [selectedImportId, setSelectedImportId] = useState<string>("");
  const [importRecords, setImportRecords] = useState<ImportRecord[]>([]);

  const [guestSelectedImportId, setGuestSelectedImportId] = useState<string>("");

  const [waitingRooms, setWaitingRooms] = useState<PkRoom[]>([]);
  const [refreshing, setRefreshing] = useState(false);
  const loadingRef = useRef(false);
  const debounceTimerRef = useRef<number | null>(null);

  useEffect(() => {
    fetchMyImportRecords().then(setImportRecords);
  }, []);

  const loadRooms = useCallback(async (force = false) => {
    if (loadingRef.current && !force) return;
    loadingRef.current = true;
    setRefreshing(true);
    try {
      const rooms = await fetchWaitingRooms();
      setWaitingRooms(rooms.filter((r) => r.hostUuid !== userInfo.uuid));
    } finally {
      setRefreshing(false);
      loadingRef.current = false;
    }
  }, [userInfo.uuid]);

  useEffect(() => {
    if (view !== "lobby") return;
    loadRooms(true);

    const channel = getPkRoomsChannel();
    channel.on(
      "postgres_changes",
      { event: "*", schema: "public", table: "pk_rooms" },
      () => {
        if (debounceTimerRef.current !== null) clearTimeout(debounceTimerRef.current);
        debounceTimerRef.current = window.setTimeout(() => loadRooms(), 500);
      }
    );
    channel.subscribe();

    const pollTimer = window.setInterval(() => loadRooms(), 4000);

    return () => {
      channel.unsubscribe();
      clearInterval(pollTimer);
      if (debounceTimerRef.current !== null) clearTimeout(debounceTimerRef.current);
    };
  }, [view, loadRooms]);

  const { room, setRoom } = usePkRoom(roomId || activeRoomId, {
    pollInterval: 3000,
    onDeleted: () => {
      if (view === "waiting") {
        showToast("房间已解散", "success");
        navigate("/pk");
      }
    },
  });

  useEffect(() => {
    if (!room) return;
    if (view === "waiting") return;
    if (closingRef.current) return;
    setIsHost(room.hostUuid === userInfo.uuid);
    setView("waiting");
  }, [room, view, userInfo.uuid]);

  useEffect(() => {
    if (!room || view !== "waiting") return;
    if (room.status === "playing") {
      navigate(`/pk/${room.id}/play`);
      return;
    }
    if (
      isHost &&
      room.status === "ready" &&
      room.hostReady &&
      room.guestReady
    ) {
      updatePkRoom(room.id, { status: "playing", currentQuestion: 0 });
    }
  }, [room, view, isHost, navigate]);

  const handleCreateRoom = async () => {
    if (sourceType === "import" && !selectedImportId) {
      showToast("请选择导入记录", "error");
      return;
    }

    let questionWords: Array<{ spelling: string; meaning: string }> = [];
    if (sourceType === "import") {
      const selectedRecord = importRecords.find((r) => r.id === selectedImportId);
      if (selectedRecord) {
        questionWords = selectedRecord.words;
      }
    } else {
      questionWords = words.map((w) => ({ spelling: w.spelling, meaning: w.meaning }));
    }

    if (questionWords.length === 0) {
      showToast("没有可用的单词，请先导入一些", "error");
      return;
    }

    const selectedRecord = importRecords.find((r) => r.id === selectedImportId);
    const result = await createPkRoom({
      questionCount,
      timePerQuestion,
      matchMode,
      sourceType,
      importRecordId: sourceType === "import" ? selectedImportId : undefined,
      importRecordTitle: sourceType === "import" ? selectedRecord?.title : undefined,
      questionWords,
      spellingRatio,
    });

    if (result) {
      closingRef.current = false;
      setActiveRoomId(result.id);
      setRoom(result);
      setIsHost(true);
      setView("waiting");
    } else {
      showToast("创建房间失败，请重试", "error");
    }
  };

  const handleJoinRoom = async (targetRoom: PkRoom) => {
    if (targetRoom.matchMode === "different") {
      if (targetRoom.sourceType === "import") {
        if (importRecords.length === 0) {
          showToast("您没有导入记录，无法加入异词本对战房间（需导入记录）", "error");
          return;
        }
      } else {
        if (words.length < targetRoom.questionCount) {
          showToast(`您的单词本只有 ${words.length} 词，至少需要 ${targetRoom.questionCount} 词`, "error");
          return;
        }
      }
    }

    const result = await joinPkRoom(targetRoom.id);
    if (result) {
      closingRef.current = false;
      setActiveRoomId(result.id);
      setRoom(result);
      setIsHost(false);
      setView("waiting");
    } else {
      showToast("加入失败，房间可能已满或已关闭", "error");
      loadRooms();
    }
  };

  const handleGuestConfirmWords = async () => {
    if (!room) return;

    let questionWords: Array<{ spelling: string; meaning: string }> = [];
    let importRecordId: string | undefined;
    let importRecordTitle: string | undefined;

    if (room.sourceType === "import") {
      if (!guestSelectedImportId) {
        showToast("请选择导入记录", "error");
        return;
      }
      const selectedRecord = importRecords.find((r) => r.id === guestSelectedImportId);
      if (!selectedRecord) {
        showToast("请选择导入记录", "error");
        return;
      }
      if (selectedRecord.wordCount < room.questionCount) {
        showToast(`该导入记录只有 ${selectedRecord.wordCount} 词，至少需要 ${room.questionCount} 词`, "error");
        return;
      }
      questionWords = selectedRecord.words;
      importRecordId = selectedRecord.id;
      importRecordTitle = selectedRecord.title;
    } else {
      if (words.length < room.questionCount) {
        showToast(`您的单词本只有 ${words.length} 词，至少需要 ${room.questionCount} 词`, "error");
        return;
      }
      questionWords = words.map((w) => ({ spelling: w.spelling, meaning: w.meaning }));
    }

    const updated = await updatePkRoom(room.id, {
      guestSourceType: room.sourceType,
      guestImportRecordId: importRecordId || "",
      guestImportRecordTitle: importRecordTitle || "",
      guestQuestionWords: questionWords,
      guestReady: true,
      status: "ready",
    });

    if (updated) {
      setRoom(updated);
      showToast("已选好词库，准备迎战！", "success");
    } else {
      showToast("设置词库失败，请重试", "error");
    }
  };

  const handleToggleReady = async () => {
    if (!room) return;
    if (!isHost && room.matchMode === "different" && !room.guestQuestionWords) {
      showToast("请先选择您的词库", "error");
      return;
    }
    const nextReady = isHost ? !room.hostReady : !room.guestReady;
    const updated = await updatePkRoom(room.id, {
      [isHost ? "hostReady" : "guestReady"]: nextReady,
    });
    if (updated) setRoom(updated);
  };

  const handleCloseWaiting = async () => {
    if (room && room.status !== "playing") {
      if (isHost) {
        const ok = await deletePkRoom(room.id);
        if (!ok) {
          showToast("关闭房间失败，请重试", "error");
          return;
        }
      } else {
        await updatePkRoom(room.id, {
          guestUuid: null,
          guestNickname: null,
          guestReady: false,
          guestSourceType: null,
          guestImportRecordId: null,
          guestImportRecordTitle: null,
          guestQuestionWords: null,
          status: "waiting",
        });
      }
    }
    closingRef.current = true;
    setActiveRoomId("");
    setRoom(null);
    setView("lobby");
    navigate("/pk");
  };

  if (view === "lobby") {
    return (
      <PkLobbyView
        waitingRooms={waitingRooms}
        refreshing={refreshing}
        onRefresh={loadRooms}
        onJoin={handleJoinRoom}
        onCreate={() => setView("create")}
        onBack={() => navigate("/")}
      />
    );
  }

  if (view === "create") {
    return (
      <PkCreateView
        matchMode={matchMode}
        sourceType={sourceType}
        questionCount={questionCount}
        timePerQuestion={timePerQuestion}
        spellingRatio={spellingRatio}
        selectedImportId={selectedImportId}
        importRecords={importRecords}
        myWordCount={words.length}
        onMatchModeChange={setMatchMode}
        onSourceTypeChange={setSourceType}
        onQuestionCountChange={setQuestionCount}
        onTimePerQuestionChange={setTimePerQuestion}
        onSpellingRatioChange={setSpellingRatio}
        onSelectedImportIdChange={setSelectedImportId}
        onBack={() => setView("lobby")}
        onCreate={handleCreateRoom}
      />
    );
  }

  if (view === "waiting" && room) {
    return (
      <PkWaitingView
        room={room}
        isHost={isHost}
        importRecords={importRecords}
        myWordCount={words.length}
        guestSelectedImportId={guestSelectedImportId}
        onGuestSelectedImportIdChange={setGuestSelectedImportId}
        onGuestConfirmWords={handleGuestConfirmWords}
        onClose={handleCloseWaiting}
        onToggleReady={handleToggleReady}
      />
    );
  }

  return null;
}
