import { create } from "zustand";
import { audioManager } from "@/utils/audioManager";
import { uploadScore, FarmSnapshot } from "@/utils/rankingApi";
import { getUserInfo } from "@/utils/userInfo";
import { useFarmStore } from "@/store/useFarmStore";
import {
  Board,
  Position,
  ConnectedGroup,
  GameState,
  Direction,
  BRICK_TYPES,
  BRICKS_PER_TYPE,
  ROWS,
  COLS,
  ItemType,
  ShopItem,
  ActiveTool,
  FROZEN_START_LEVEL,
} from "@/types/game";
import {
  initializeBoard,
  findConnectedGroup,
  findAdjacentSameType,
  findPushChain,
  canPushChain,
  pushChain,
  clearPair,
  countRemainingBricks,
  deepCloneBoard,
  findCellAdjacentPairs,
  findFirstEliminablePair,
  hasAnyEliminableMove,
  unfreezeAdjacent,
} from "@/utils/gameLogic";
import { showToast } from "@/utils/toast";

const STORAGE_KEY_PROGRESS = "block_game_progress";

function loadProgress(): { coins: number; sunlight: number; inventory: GameState["inventory"] } {
  try {
    const raw = localStorage.getItem(STORAGE_KEY_PROGRESS);
    if (raw) {
      const data = JSON.parse(raw);
      return {
        coins: data.coins || 0,
        sunlight: data.sunlight || 0,
        inventory: data.inventory || { restart: 1, undo: 1, hint: 1, swap: 0, clearType: 0, shuffle: 1 },
      };
    }
  } catch (e) {
    console.error("读取进度失败", e);
  }
  return { coins: 0, sunlight: 0, inventory: { restart: 1, undo: 1, hint: 1, swap: 0, clearType: 0, shuffle: 1 } };
}

let saveProgressTimer: number | null = null;
function saveProgress(state: { coins: number; sunlight: number; inventory: GameState["inventory"] }) {
  if (saveProgressTimer !== null) {
    clearTimeout(saveProgressTimer);
  }
  saveProgressTimer = window.setTimeout(() => {
    saveProgressTimer = null;
    try {
      localStorage.setItem(STORAGE_KEY_PROGRESS, JSON.stringify({
        coins: state.coins,
        sunlight: state.sunlight,
        inventory: state.inventory,
      }));
    } catch (e) {
      console.error("保存进度失败", e);
    }
  }, 300);
}

let saveGameTimer: number | null = null;
let saveGamePending: null | {
  isWon: boolean;
  board: Board;
  level: number;
  score: number;
  clearedPairs: number;
  remainingBricks: number;
  moveHistory: unknown[];
  isFailed: boolean;
  failedClearedByQuiz: boolean;
} = null;
function flushSaveGame() {
  saveGameTimer = null;
  const s = saveGamePending;
  saveGamePending = null;
  if (!s || s.isWon) return;
  const saveData = {
    board: s.board,
    level: s.level,
    score: s.score,
    clearedPairs: s.clearedPairs,
    remainingBricks: s.remainingBricks,
    moveHistory: s.moveHistory,
    isFailed: s.isFailed,
    failedClearedByQuiz: s.failedClearedByQuiz,
    savedAt: Date.now(),
  };
  try {
    localStorage.setItem("block_game_save", JSON.stringify(saveData));
  } catch (e) {
    console.error("保存失败", e);
  }
}

interface PendingState {
  board: Board;
  selectedCell: Position | null;
  pairCandidates: Position[];
  selectedGroup: ConnectedGroup | null;
  score: number;
  clearedPairs: number;
  remainingBricks: number;
  isWon: boolean;
  moveHistory: Board[];
}

interface GameStore extends GameState {
  pendingState: PendingState | null;
  shopItems: ShopItem[];
  initGame: (resetLevel?: boolean, resetProgress?: boolean) => void;
  selectCell: (row: number, col: number) => void;
  finalizeDragMove: (direction: Direction, steps: number) => boolean;
  clearSelection: () => void;
  applyItem: (item: ItemType) => boolean;
  addItem: (item: ItemType, count: number) => void;
  addCoins: (amount: number) => void;
  spendCoins: (amount: number) => boolean;
  addSunlight: (amount: number) => void;
  spendSunlight: (amount: number) => boolean;
  finishClearingAnimation: () => void;
  findSameTypePositions: (row: number, col: number) => Position[];
  clearHint: () => void;
  nextLevel: () => void;
  closeFailModal: () => void;
  checkAndClearFailAfterQuiz: () => void;
  checkDeadlock: () => boolean;
  refreshShop: () => void;
  buyShopItem: (itemId: string) => boolean;
  setActiveTool: (tool: ActiveTool) => void;
  cancelTool: () => void;
  handleToolCellClick: (row: number, col: number) => void;
  simulateWin: () => void;
  simulateFail: () => void;
  saveGame: () => void;
  loadGame: () => boolean;
}

const TOTAL_BRICKS = BRICK_TYPES * BRICKS_PER_TYPE;

const generateShopItems = (): ShopItem[] => {
  const types: ItemType[] = ["restart", "undo", "hint", "swap", "clearType", "shuffle"];
  const prices: Record<ItemType, number> = { restart: 5, undo: 2, hint: 3, swap: 5, clearType: 6, shuffle: 11 };
  const items: ShopItem[] = [];
  const shuffled = [...types].sort(() => Math.random() - 0.5);
  for (let i = 0; i < 4; i++) {
    const type = shuffled[i % shuffled.length];
    items.push({
      id: `shop_${Date.now()}_${i}`,
      type,
      price: prices[type],
    });
  }
  return items;
};

export const useGameStore = create<GameStore>((set, get) => {
  const initialProgress = loadProgress();
  return {
  board: [],
  selectedGroup: null,
  selectedCell: null,
  pairCandidates: [],
  score: 0,
  clearedPairs: 0,
  remainingBricks: TOTAL_BRICKS,
  isWon: false,
  isFailed: false,
  failedClearedByQuiz: false,
  level: 1,
  moveHistory: [],
  clearingCells: [],
  hintCells: [],
  coins: initialProgress.coins,
  sunlight: initialProgress.sunlight,
  inventory: initialProgress.inventory,
  activeTool: null,
  swapFirstCell: null,
  shopItems: [],
  pendingState: null,

  initGame: (resetLevel = true, resetProgress = false) => {
    const currentLevel = get().level;
    const board = initializeBoard(resetLevel ? 1 : currentLevel);
    const currentShop = get().shopItems;
    
    // 如果需要重置进度，则重置金币和道具次数
    const resetValues = resetProgress ? {
      coins: 0,
      inventory: { restart: 1, undo: 1, hint: 1, swap: 0, clearType: 0, shuffle: 1 },
    } : {
      coins: get().coins,
      inventory: get().inventory,
    };
    
    set({
      board,
      selectedGroup: null,
      selectedCell: null,
      pairCandidates: [],
      score: 0,
      clearedPairs: 0,
      remainingBricks: TOTAL_BRICKS,
      isWon: false,
      isFailed: false,
      failedClearedByQuiz: false,
      level: resetLevel ? 1 : currentLevel,
      moveHistory: [],
      clearingCells: [],
      hintCells: [],
      ...resetValues,
      activeTool: null,
      swapFirstCell: null,
      shopItems: currentShop.length > 0 ? currentShop : generateShopItems(),
      pendingState: null,
    });
    if (resetProgress) {
      saveProgress({ ...resetValues, sunlight: get().sunlight });
    }
  },

  selectCell: (row: number, col: number) => {
    const { board, activeTool, isWon, isFailed, clearingCells, pendingState } = get();
    if (isWon || isFailed || clearingCells.length > 0 || pendingState) return;

    if (activeTool) {
      get().handleToolCellClick(row, col);
      return;
    }

    const { selectedCell, pairCandidates, selectedGroup } = get();

    const cell = board[row]?.[col];
    if (!cell) return;

    if (cell.brick === null) {
      get().clearSelection();
      return;
    }

    // 冰冻方块不能被选中
    if (cell.frozen) {
      showToast("冰冻方块无法操作", "error");
      return;
    }

    if (selectedCell) {
      const isCandidate = pairCandidates.some(
        (p) => p.row === row && p.col === col
      );
      if (isCandidate) {
        const savedBoard = deepCloneBoard(board);
        const newBoard = clearPair(board, selectedCell, { row, col });
        const remaining = countRemainingBricks(newBoard);

        const clearing: Position[] = [selectedCell, { row, col }];

        audioManager.playClearSfx();

        set({
          clearingCells: clearing,
          failedClearedByQuiz: false,
          pendingState: {
            board: newBoard,
            selectedCell: null,
            pairCandidates: [],
            selectedGroup: null,
            score: get().score + 2,
            clearedPairs: get().clearedPairs + 1,
            remainingBricks: remaining,
            isWon: remaining === 0,
            moveHistory: [...get().moveHistory, savedBoard],
          },
        });
        return;
      }

      if (selectedCell.row === row && selectedCell.col === col) {
        get().clearSelection();
        return;
      }

      const inCurrentGroup =
        selectedGroup?.positions.some(
          (p) => p.row === row && p.col === col
        ) ?? false;
      if (inCurrentGroup) {
        get().clearSelection();
        return;
      }
    }

    const candidates = findAdjacentSameType(board, row, col);
    const group = findConnectedGroup(board, row, col);

    set({
      selectedCell: { row, col },
      pairCandidates: candidates,
      selectedGroup: group,
    });
  },

  finalizeDragMove: (direction: Direction, steps: number): boolean => {
    const { board, selectedCell, isWon, isFailed, clearingCells, pendingState } = get();
    if (isWon || isFailed || !selectedCell || steps <= 0 || clearingCells.length > 0 || pendingState) return false;

    const DIR_DELTA: Record<Direction, [number, number]> = {
      up: [-1, 0],
      down: [1, 0],
      left: [0, -1],
      right: [0, 1],
    };
    const [dr, dc] = DIR_DELTA[direction];

    const savedBoard = deepCloneBoard(board);
    let currentBoard = board;

    const initialChain = findPushChain(board, selectedCell.row, selectedCell.col, direction);
    if (initialChain.length === 0) return false;

    let chain = initialChain;
    for (let i = 0; i < steps; i++) {
      if (!canPushChain(currentBoard, chain, direction)) return false;
      currentBoard = pushChain(currentBoard, chain, direction);
      chain = chain.map((p) => ({ row: p.row + dr, col: p.col + dc }));
    }

    const newSelectedPos: Position = {
      row: selectedCell.row + steps * dr,
      col: selectedCell.col + steps * dc,
    };

    const pairs = findCellAdjacentPairs(currentBoard, newSelectedPos);
    if (pairs.length === 0) return false;

    const hasMultiplePairs = pairs.length > 1;
    const resultBoard = hasMultiplePairs ? currentBoard : clearPair(currentBoard, pairs[0][0], pairs[0][1]);
    const clearedCount = hasMultiplePairs ? 0 : 1;
    const clearing: Position[] = hasMultiplePairs ? [] : [pairs[0][0], pairs[0][1]];

    const clearedBoard = resultBoard;
    const remaining = countRemainingBricks(clearedBoard);
    const currentScore = get().score;
    const currentCleared = get().clearedPairs;

    const newCandidates = findAdjacentSameType(clearedBoard, newSelectedPos.row, newSelectedPos.col);
    const newGroup = findConnectedGroup(clearedBoard, newSelectedPos.row, newSelectedPos.col);

    if (hasMultiplePairs) {
      set({
        board: currentBoard,
        selectedCell: newSelectedPos,
        pairCandidates: newCandidates,
        selectedGroup: newGroup,
        moveHistory: [...get().moveHistory, savedBoard],
        failedClearedByQuiz: false,
      });
    } else {
      audioManager.playClearSfx();
      set({
        board: currentBoard,
        selectedCell: newSelectedPos,
        clearingCells: clearing,
        failedClearedByQuiz: false,
        pendingState: {
          board: clearedBoard,
          selectedCell: null,
          pairCandidates: [],
          selectedGroup: null,
          score: currentScore + clearedCount * 1,
          clearedPairs: currentCleared + clearedCount,
          remainingBricks: remaining,
          isWon: remaining === 0,
          moveHistory: [...get().moveHistory, savedBoard],
        },
      });
    }
    return true;
  },

  finishClearingAnimation: () => {
    const { pendingState, clearingCells } = get();
    if (!pendingState) return;

    const willWin = pendingState.isWon;

    // 解冻：检查被消除位置相邻的冰冻方块
    const finalBoard = deepCloneBoard(pendingState.board);
    if (clearingCells.length > 0) {
      const toUnfreeze = unfreezeAdjacent(finalBoard, clearingCells);
      for (const pos of toUnfreeze) {
        finalBoard[pos.row][pos.col].frozen = false;
      }
    }

    set({
      board: finalBoard,
      selectedCell: pendingState.selectedCell,
      pairCandidates: pendingState.pairCandidates,
      selectedGroup: pendingState.selectedGroup,
      score: pendingState.score,
      clearedPairs: pendingState.clearedPairs,
      remainingBricks: pendingState.remainingBricks,
      isWon: pendingState.isWon,
      moveHistory: pendingState.moveHistory,
      clearingCells: [],
      pendingState: null,
    });
    if (willWin) {
      audioManager.playWinSfx();
    }
  },

  findSameTypePositions: (row: number, col: number): Position[] => {
    const { board } = get();
    const cell = board[row]?.[col];
    if (!cell || cell.brick === null) return [];
    const type = cell.brick;
    const result: Position[] = [];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (r === row && c === col) continue;
        if (board[r][c].brick === type) {
          result.push({ row: r, col: c });
        }
      }
    }
    return result;
  },

  clearSelection: () => {
    set({
      selectedGroup: null,
      selectedCell: null,
      pairCandidates: [],
    });
  },

  applyItem: (item: ItemType): boolean => {
    const { inventory, isWon, isFailed, clearingCells, pendingState, moveHistory, board } = get();
    if (inventory[item] <= 0) return false;

    if (item === "restart") {
      const currentCoins = get().coins;
      const currentInventory = { ...get().inventory, restart: get().inventory.restart - 1 };
      const newBoard = initializeBoard(get().level);
      set({
        board: newBoard,
        selectedGroup: null,
        selectedCell: null,
        pairCandidates: [],
        score: 0,
        clearedPairs: 0,
        remainingBricks: TOTAL_BRICKS,
        isWon: false,
        isFailed: false,
        failedClearedByQuiz: false,
        moveHistory: [],
        clearingCells: [],
        hintCells: [],
        coins: currentCoins,
        inventory: currentInventory,
        pendingState: null,
      });
      return true;
    }

    if (item === "undo") {
      if (moveHistory.length === 0 || isWon || isFailed || clearingCells.length > 0 || pendingState) return false;
      const prevBoard = moveHistory[moveHistory.length - 1];
      const remaining = countRemainingBricks(prevBoard);
      set({
        board: prevBoard,
        selectedGroup: null,
        selectedCell: null,
        pairCandidates: [],
        moveHistory: moveHistory.slice(0, -1),
        remainingBricks: remaining,
        isWon: false,
        failedClearedByQuiz: false,
        inventory: { ...get().inventory, undo: get().inventory.undo - 1 },
      });
      return true;
    }

    if (item === "hint") {
      if (isWon || isFailed || clearingCells.length > 0 || pendingState) return false;
      const pair = findFirstEliminablePair(board);
      if (!pair) {
        showToast("未找到可消除的对", "error");
        return false;
      }
      set({
        hintCells: [pair[0], pair[1]],
        inventory: { ...get().inventory, hint: get().inventory.hint - 1 },
      });
      return true;
    }

    if (item === "swap") {
      if (isWon || isFailed || clearingCells.length > 0 || pendingState) return false;
      if (get().remainingBricks < 2) return false;
      set({
        activeTool: "swap",
        swapFirstCell: null,
        selectedCell: null,
        selectedGroup: null,
        pairCandidates: [],
        hintCells: [],
      });
      return true;
    }

    if (item === "clearType") {
      if (isWon || isFailed || clearingCells.length > 0 || pendingState) return false;
      if (get().remainingBricks < 1) return false;
      set({
        activeTool: "clearType",
        selectedCell: null,
        selectedGroup: null,
        pairCandidates: [],
        hintCells: [],
      });
      return true;
    }

    if (item === "shuffle") {
      if (isWon || isFailed || clearingCells.length > 0 || pendingState) return false;
      if (get().remainingBricks < 2) return false;

      const savedBoard = deepCloneBoard(board);
      type BrickEntry = { brick: number; frozen: boolean };
      const entries: BrickEntry[] = [];
      const positions: Position[] = [];

      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          if (board[r][c].brick !== null) {
            entries.push({ brick: board[r][c].brick!, frozen: board[r][c].frozen });
            positions.push({ row: r, col: c });
          }
        }
      }

      for (let i = entries.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [entries[i], entries[j]] = [entries[j], entries[i]];
      }

      const newBoard = deepCloneBoard(board);
      positions.forEach((pos, idx) => {
        newBoard[pos.row][pos.col].brick = entries[idx].brick;
        newBoard[pos.row][pos.col].frozen = entries[idx].frozen;
      });

      set({
        board: newBoard,
        selectedGroup: null,
        selectedCell: null,
        pairCandidates: [],
        hintCells: [],
        moveHistory: [...get().moveHistory, savedBoard],
        failedClearedByQuiz: false,
        inventory: { ...get().inventory, shuffle: get().inventory.shuffle - 1 },
      });
      return true;
    }

    return false;
  },

  addItem: (item: ItemType, count: number) => {
    const newInventory = {
      ...get().inventory,
      [item]: get().inventory[item] + count,
    };
    set({ inventory: newInventory });
    saveProgress({ coins: get().coins, sunlight: get().sunlight, inventory: newInventory });
  },

  addCoins: (amount: number) => {
    const newCoins = get().coins + amount;
    set({ coins: newCoins });
    saveProgress({ coins: newCoins, sunlight: get().sunlight, inventory: get().inventory });
  },

  spendCoins: (amount: number): boolean => {
    if (get().coins < amount) return false;
    const newCoins = get().coins - amount;
    set({ coins: newCoins });
    saveProgress({ coins: newCoins, sunlight: get().sunlight, inventory: get().inventory });
    return true;
  },

  addSunlight: (amount: number) => {
    const newSunlight = get().sunlight + amount;
    set({ sunlight: newSunlight });
    saveProgress({ coins: get().coins, sunlight: newSunlight, inventory: get().inventory });
  },

  spendSunlight: (amount: number): boolean => {
    if (get().sunlight < amount) return false;
    const newSunlight = get().sunlight - amount;
    set({ sunlight: newSunlight });
    saveProgress({ coins: get().coins, sunlight: newSunlight, inventory: get().inventory });
    return true;
  },

  setActiveTool: (tool: ActiveTool) => {
    set({
      activeTool: tool,
      swapFirstCell: null,
    });
  },

  cancelTool: () => {
    set({
      activeTool: null,
      swapFirstCell: null,
    });
  },

  handleToolCellClick: (row: number, col: number) => {
    const { board, activeTool, swapFirstCell } = get();
    const cell = board[row]?.[col];
    if (!cell) return;

    if (activeTool === "swap") {
      if (cell.brick === null) return;

      // 冰冻方块禁止交换
      if (cell.frozen) {
        showToast("冰冻方块无法交换", "error");
        return;
      }

      if (swapFirstCell === null) {
        set({ swapFirstCell: { row, col } });
      } else {
        if (swapFirstCell.row === row && swapFirstCell.col === col) {
          set({ swapFirstCell: null });
          return;
        }

        const savedBoard = deepCloneBoard(board);
        const newBoard = deepCloneBoard(board);
        const temp = newBoard[swapFirstCell.row][swapFirstCell.col].brick;
        newBoard[swapFirstCell.row][swapFirstCell.col].brick = newBoard[row][col].brick;
        newBoard[row][col].brick = temp;

        set({
          board: newBoard,
          activeTool: null,
          swapFirstCell: null,
          selectedCell: null,
          selectedGroup: null,
          pairCandidates: [],
          hintCells: [],
          moveHistory: [...get().moveHistory, savedBoard],
          failedClearedByQuiz: false,
          inventory: { ...get().inventory, swap: get().inventory.swap - 1 },
        });
      }
      return;
    }

    if (activeTool === "clearType") {
      if (cell.brick === null) return;

      const typeToClear = cell.brick;
      const savedBoard = deepCloneBoard(board);
      const newBoard = deepCloneBoard(board);
      const cleared: Position[] = [];

      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          if (newBoard[r][c].brick === typeToClear) {
            cleared.push({ row: r, col: c });
            newBoard[r][c].brick = null;
          }
        }
      }

      audioManager.playClearSfx();

      const remaining = countRemainingBricks(newBoard);
      const clearedCount = Math.floor(cleared.length / 2);

      set({
        board,
        clearingCells: cleared,
        failedClearedByQuiz: false,
        pendingState: {
          board: newBoard,
          selectedCell: null,
          pairCandidates: [],
          selectedGroup: null,
          score: get().score + clearedCount * 1,
          clearedPairs: get().clearedPairs + clearedCount,
          remainingBricks: remaining,
          isWon: remaining === 0,
          moveHistory: [...get().moveHistory, savedBoard],
        },
        activeTool: null,
        inventory: { ...get().inventory, clearType: get().inventory.clearType - 1 },
      });
      return;
    }
  },

  clearHint: () => {
    set({ hintCells: [] });
  },

  nextLevel: () => {
    const currentLevel = get().level;
    const currentCoins = get().coins;
    const currentSunlight = get().sunlight;
    const currentInventory = get().inventory;
    const board = initializeBoard(currentLevel + 1);
    const reward = Math.min(2 + currentLevel, 12);
    const nextLevelValue = currentLevel + 1;
    const prevBest = parseInt(localStorage.getItem("block_game_best") || "0");
    if (nextLevelValue > prevBest) {
      localStorage.setItem("block_game_best", String(nextLevelValue));
      const userInfo = getUserInfo();
      const farmState = useFarmStore.getState();
      const farmData: FarmSnapshot = {
        plantedCrops: farmState.plantedCrops.map((c) => ({
          id: c.id,
          seedType: c.seedType,
          plantedAt: c.plantedAt,
          plotIndex: c.plotIndex,
        })),
        stolenRecords: farmState.stolenRecords || [],
        warehouse: farmState.warehouse,
        totalPlots: farmState.totalPlots,
        openedPlots: farmState.openedPlots,
        unlockedSeeds: farmState.unlockedSeeds,
        snapshotAt: Date.now(),
      };
      uploadScore(userInfo.uuid, userInfo.nickname, nextLevelValue, farmData);
    }
    set({
      board,
      selectedGroup: null,
      selectedCell: null,
      pairCandidates: [],
      score: 0,
      clearedPairs: 0,
      remainingBricks: TOTAL_BRICKS,
      isWon: false,
      isFailed: false,
      failedClearedByQuiz: false,
      level: nextLevelValue,
      moveHistory: [],
      clearingCells: [],
      hintCells: [],
      coins: currentCoins + reward,
      sunlight: currentSunlight,
      inventory: currentInventory,
      activeTool: null,
      swapFirstCell: null,
      shopItems: generateShopItems(),
      pendingState: null,
    });
    saveProgress({ coins: currentCoins + reward, sunlight: currentSunlight, inventory: currentInventory });

    // 第3关提示：出现冰冻方块
    if (nextLevelValue === FROZEN_START_LEVEL) {
      showToast("难度提升，出现冰冻方块", "success");
    }
  },

  refreshShop: () => {
    // 检查积分是否足够
    if (get().coins < 1) return;
    // 消耗1积分
    get().spendCoins(1);
    // 刷新商品
    set({ shopItems: generateShopItems() });
  },

  buyShopItem: (itemId: string): boolean => {
    const item = get().shopItems.find((i) => i.id === itemId);
    if (!item) return false;
    if (!get().spendCoins(item.price)) return false;
    get().addItem(item.type, 1);
    set({
      shopItems: get().shopItems.filter((i) => i.id !== itemId),
    });
    return true;
  },

  checkDeadlock: (): boolean => {
    const { board, remainingBricks, isWon, failedClearedByQuiz } = get();
    if (isWon || remainingBricks === 0) return false;
    if (failedClearedByQuiz) return false;
    const pair = findFirstEliminablePair(board);
    if (pair) return false;
    // 二次验证：检查更复杂的"推动让路"场景
    if (hasAnyEliminableMove(board)) return false;
    // 确认死锁
    set({ isFailed: true });
    audioManager.playFailSfx();
    return true;
  },

  closeFailModal: () => {
    set({ isFailed: false });
  },

  checkAndClearFailAfterQuiz: () => {
    const { isFailed } = get();
    if (isFailed) {
      set({ isFailed: false, failedClearedByQuiz: true });
      setTimeout(() => get().saveGame(), 100);
    }
  },

  simulateWin: () => {
    const { board } = get();
    const pair = findFirstEliminablePair(board);
    if (!pair) return;

    const newBoard = deepCloneBoard(board);
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (
          !(r === pair[0].row && c === pair[0].col) &&
          !(r === pair[1].row && c === pair[1].col)
        ) {
          newBoard[r][c].brick = null;
        }
      }
    }

    set({
      board: newBoard,
      remainingBricks: 2,
      isWon: false,
      isFailed: false,
      moveHistory: [],
      selectedCell: null,
      selectedGroup: null,
      pairCandidates: [],
      clearingCells: [],
      hintCells: [],
    });
  },

  simulateFail: () => {
    const { board } = get();
    const newBoard = deepCloneBoard(board);

    // 重新分配类型，确保同行同列直线方向上无同类型方块（死锁）
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        newBoard[r][c].brick = (r + c * 7) % BRICK_TYPES;
      }
    }

    set({
      board: newBoard,
      remainingBricks: ROWS * COLS,
      isWon: false,
      isFailed: false,
      moveHistory: [],
      selectedCell: null,
      selectedGroup: null,
      pairCandidates: [],
      clearingCells: [],
      hintCells: [],
    });
  },

  saveGame: () => {
    const state = get();
    if (state.isWon) return;
    saveGamePending = state;
    if (saveGameTimer !== null) {
      clearTimeout(saveGameTimer);
    }
    saveGameTimer = window.setTimeout(flushSaveGame, 500);
  },

  loadGame: (): boolean => {
    try {
      const raw = localStorage.getItem("block_game_save");
      if (!raw) return false;
      const data = JSON.parse(raw);
      if (!data.board || !data.board.length) return false;
      set({
        board: data.board,
        level: data.level || 1,
        score: data.score || 0,
        clearedPairs: data.clearedPairs || 0,
        remainingBricks: data.remainingBricks || TOTAL_BRICKS,
        moveHistory: data.moveHistory || [],
        activeTool: null,
        swapFirstCell: null,
        selectedGroup: null,
        selectedCell: null,
        pairCandidates: [],
        isWon: false,
        isFailed: data.isFailed || false,
        failedClearedByQuiz: data.failedClearedByQuiz || false,
        clearingCells: [],
        hintCells: [],
        shopItems: generateShopItems(),
        pendingState: null,
      });
      return true;
    } catch (e) {
      console.error("读取失败", e);
      return false;
    }
  },
}});

useGameStore.getState().loadGame();
