interface Props {
  myName: string;
  myScore: number;
  myCorrect: number;
  opponentName: string | undefined;
  opponentScore: number;
  opponentCorrect: number;
  questionIndex: number;
  totalQuestions: number;
}

export function ScoreBoard({
  myName,
  myScore,
  opponentName,
  opponentScore,
  questionIndex,
  totalQuestions,
}: Props) {
  const progress = totalQuestions > 0 ? ((questionIndex + 1) / totalQuestions) * 100 : 0;

  return (
    <div className="flex items-center justify-between mb-4">
      <div className="flex items-center gap-2">
        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center shadow-lg shadow-emerald-500/30">
          <span className="text-white text-sm font-bold">{myName.slice(0, 1)}</span>
        </div>
        <div>
          <p className="text-slate-200 text-xs">{myName}</p>
          <p className="text-emerald-300 font-bold">{myScore}</p>
        </div>
      </div>

      <div className="text-center">
        <p className="text-slate-500 text-xs">
          {questionIndex + 1} / {totalQuestions}
        </p>
        <div className="w-24 h-1.5 bg-slate-700 rounded-full overflow-hidden mt-1">
          <div
            className="h-full bg-gradient-to-r from-emerald-400 to-teal-500 transition-all"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      <div className="flex items-center gap-2">
        <div className="text-right">
          <p className="text-slate-200 text-xs">{opponentName || "对手"}</p>
          <p className="text-amber-300 font-bold">{opponentScore}</p>
        </div>
        <div className="w-10 h-10 rounded-full bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center shadow-lg shadow-amber-500/30">
          <span className="text-white text-sm font-bold">{opponentName?.slice(0, 1) || "?"}</span>
        </div>
      </div>
    </div>
  );
}
